export function translateModuleMessage(id: string, language: UserLanguage, message: string): string {
  const dictionary = translationsForModule(id)[language];
  const exact = dictionary?.[message];
  if (exact) return exact;
  if (id === "core-events") {
    const patterns: Array<{ pattern: RegExp; key: string; values: (match: RegExpMatchArray) => Record<string, string> }> = [
      { pattern: /^Updated (\d+) gatherings in the recurring series\.$/, key: "Updated {count} gatherings in the recurring series.", values: (match) => ({ count: match[1] }) },
      { pattern: /^Added (\d+) recurring gatherings to the schedule\.$/, key: "Added {count} recurring gatherings to the schedule.", values: (match) => ({ count: match[1] }) },
      { pattern: /^(.+) was updated\.$/, key: "{title} was updated.", values: (match) => ({ title: match[1] }) },
      { pattern: /^(.+) was added to the schedule\.$/, key: "{title} was added to the schedule.", values: (match) => ({ title: match[1] }) },
      { pattern: /^Removed (\d+) gatherings in the recurring series\.$/, key: "Removed {count} gatherings in the recurring series.", values: (match) => ({ count: match[1] }) },
      { pattern: /^Attendance saved for (.+)\.$/, key: "Attendance saved for {title}.", values: (match) => ({ title: match[1] }) },
      { pattern: /^Follow-up for (.+) was saved\.$/, key: "Follow-up for {person} was saved.", values: (match) => ({ person: match[1] }) },
    ];
    for (const item of patterns) {
      const match = message.match(item.pattern);
      const template = dictionary?.[item.key];
      if (match && template) return Object.entries(item.values(match)).reduce((value, [key, replacement]) => value.replace(`{${key}}`, replacement), template);
    }
  }
  if (id === "sync") {
    const patterns: Array<{ pattern: RegExp; key: string; values: (match: RegExpMatchArray) => Record<string, string> }> = [
      { pattern: /^ChurchTools rejected the token or does not grant read access to (.+)\.$/, key: "ChurchTools rejected the token or does not grant read access to {endpoint}.", values: (match) => ({ endpoint: match[1] }) },
      { pattern: /^ChurchTools returned HTTP (\d+) for (.+)\.$/, key: "ChurchTools returned HTTP {status} for {endpoint}.", values: (match) => ({ status: match[1], endpoint: match[2] }) },
      { pattern: /^ChurchTools did not return a member list for group “(.+)”\. Check the API path and group read permissions\.$/, key: "ChurchTools did not return a member list for group “{group}”. Check the API path and group read permissions.", values: (match) => ({ group: match[1] }) },
      { pattern: /^The local event time (\S+) (\S+) does not exist in (.+) because of a daylight-saving change\.$/, key: "The local event time {date} {time} does not exist in {timeZone} because of a daylight-saving change.", values: (match) => ({ date: match[1], time: match[2], timeZone: match[3] }) },
      { pattern: /^The local event time (\S+) (\S+) occurs twice in (.+) because of a daylight-saving change\.$/, key: "The local event time {date} {time} occurs twice in {timeZone} because of a daylight-saving change.", values: (match) => ({ date: match[1], time: match[2], timeZone: match[3] }) },
    ];
    for (const item of patterns) {
      const match = message.match(item.pattern);
      const template = dictionary?.[item.key];
      if (match && template) return Object.entries(item.values(match)).reduce((value, [key, replacement]) => value.replace(`{${key}}`, replacement), template);
    }
  }
  return message;
}

export function translateKnownModuleMessage(language: UserLanguage, message: string): string {
  for (const id of ["core-admin", "core-people", "core-groups", "core-events", "core-resources", "sync"]) {
    const translated = translateModuleMessage(id, language, message);
    if (translated !== message) return translated;
  }
  return message;
}
